using System;
using System.IO;
using System.Linq;
using CircuitoStudio;
internal static class VoltageDropTests {
 static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}
 static void Near(double a,double b,string label){Check(Math.Abs(a-b)<1e-9,label);}
 static string Status(Project p,Circuit c){return Engineering.Analyze(p).Checks.Single(x=>x.CircuitId==c.Id&&x.Rule=="Queda de tensão").Status;}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
 static Project Make(){var p=new Project();p.Source.LineVoltage=400;p.Source.MaxDropPercent=4;var b=new Board{Id="Q",Voltage=400};b.Circuits.Add(new Circuit{Id="C",Voltage=230.94,Phases=PhaseMode.Monofasico,PhaseLabel="L1",PowerKw=2.3094,PowerFactor=1,LengthM=100,CableMm2=10});p.Boards.Add(b);b.Circuits[0].Cable.ResistanceOhmKm=1;b.Circuits[0].Cable.ReactanceOhmKm=.5;return p;}
 public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"voltage-drop-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=Make();var c=p.Boards[0].Circuits[0];var row=Engineering.Analyze(p).For(c);Near(row.CurrentA,10,"mono independent input current");Near(row.VoltageDropV,2,"mono resistive loop voltage drop");Near(row.VoltageDropPercent,200/230.94,"mono drop percent units");Check(Status(p,c)=="OK","inherits project limit");
  c.VoltageDropLimitPercent=.5;Check(Status(p,c)=="Falha","local limit overrides larger global limit");c.VoltageDropLimitPercent=1;Check(Status(p,c)=="OK","local limit permits acceptable drop");var option=new CableOption{Name="Ensaio",Material="Cu",Insulation="PVC",Installation="Informado",Reference="Tabela sintética",SectionMm2=10,IzA=100,ResistanceOhmKm=1,ReactanceOhmKm=.5};Check(CableSelection.Evaluate(p,c,option).Status!="Não atende","cable preselection honors permissive local limit");c.VoltageDropLimitPercent=.5;Check(CableSelection.Evaluate(p,c,option).Status=="Não atende","cable preselection rejects same drop under stricter local limit");c.VoltageDropLimitPercent=1;p.Source.MaxDropPercent=.01;Check(Status(p,c)=="OK","explicit local limit overrides smaller global limit");c.VoltageDropLimitPercent=null;Check(Status(p,c)=="Falha","clearing local limit restores project inheritance");p.Source.MaxDropPercent=4;
  c.Phases=PhaseMode.Trifasico;c.PhaseLabel="ABC";c.Voltage=400;c.PowerKw=4*Math.Sqrt(3)*.8;c.PowerFactor=.8;row=Engineering.Analyze(p).For(c);Near(row.CurrentA,10,"three phase independent current");Near(row.VoltageDropV,Math.Sqrt(3)*1.1,"three phase resistive and reactive drop");c.VoltageDropLimitPercent=.48;Check(Status(p,c)=="OK","three phase drop below .48 percent");c.VoltageDropLimitPercent=.47;Check(Status(p,c)=="Falha","three phase drop above .47 percent");c.VoltageDropLimitPercent=row.AccumulatedDropPercent;Check(Status(p,c)=="OK","exact threshold accepted");
  c.PowerKw=0;c.ReactiveKvarOverride=-4*Math.Sqrt(3);c.Cable.ReactanceOhmKm=1;c.VoltageDropLimitPercent=.4;row=Engineering.Analyze(p).For(c);Near(row.VoltageDropV,-Math.Sqrt(3),"capacitive rise has negative sign");Check(Status(p,c)=="Falha","absolute voltage rise compared against limit");c.VoltageDropLimitPercent=.5;Check(Status(p,c)=="OK","capacitive rise under limit accepted");
  c.Cable.ResistanceOhmKm=0;c.CableMm2=0;Check(Status(p,c)=="Pendente","missing cable impedance stays pending despite local limit");c.Cable.ResistanceOhmKm=1;c.CableMm2=10;
  var q1=new Board{Id="A",Voltage=400};var q2=new Board{Id="B",Voltage=400};var q3=new Board{Id="D",Voltage=400};p=new Project();p.Source.LineVoltage=400;p.Boards.AddRange(new[]{q1,q2,q3});
  var a=new Circuit{Id="A1",ChildBoardId="B"};var b=new Circuit{Id="B1",ChildBoardId="D"};var d=new Circuit{Id="D1",PowerKw=4*Math.Sqrt(3),VoltageDropLimitPercent=.5};q1.Circuits.Add(a);q2.Circuits.Add(b);q3.Circuits.Add(d);
  foreach(var x in new[]{a,b,d}){x.Phases=PhaseMode.Trifasico;x.PhaseLabel="ABC";x.Voltage=400;x.LengthM=50;x.Cable.ResistanceOhmKm=1;x.Cable.ReactanceOhmKm=0;}
  row=Engineering.Analyze(p).For(d);Near(row.VoltageDropPercent,Math.Sqrt(3)*.125,"local drop analytical reference");Near(row.AccumulatedDropPercent,Math.Sqrt(3)*.375,"three-level drop accumulated");Check(Status(p,d)=="Falha","local threshold applies to accumulated path rather than local segment");Check(Status(p,a)=="OK"&&Status(p,b)=="OK","other circuit checks keep inherited limits");
  string file=Path.Combine(dir,"limits.circuito");p.Save(file);Check(File.ReadAllText(file).Contains("\"FileVersion\":3"),"explicit drop limits require format 3");var restored=Project.Load(file);Near(restored.Boards[2].Circuits[0].VoltageDropLimitPercent.Value,.5,"local limit persists");Near(Engineering.Analyze(restored).For(restored.Boards[2].Circuits[0]).AccumulatedDropPercent,row.AccumulatedDropPercent,"reopened drop reproducible");
  string saved=File.ReadAllText(file);File.WriteAllText(file,saved.Replace("\"FileVersion\":3","\"FileVersion\":2"));Reject(delegate{Project.Load(file);},"legacy-tagged explicit limit rejected to avoid silent data loss");File.WriteAllText(file,saved);
  foreach(double invalid in new[]{0.0,-1,double.NaN,double.PositiveInfinity,100.01}){d.VoltageDropLimitPercent=invalid;Reject(p.Validate,"invalid limit rejected: "+invalid);}d.VoltageDropLimitPercent=.5;
  string report=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(report.Contains("Limite de queda acumulada do circuito: 0,500% (definido no circuito)"),"report identifies local limit units and source");Check(report.Contains("herdado do projeto"),"report identifies inherited limits");
  var clone=ProjectEditing.DuplicateCircuit(p,q3,d);Check(clone.VoltageDropLimitPercent==d.VoltageDropLimitPercent,"duplicate keeps explicit limit");
  Console.WriteLine("PASS: "+n+" voltage-drop assertions including analytical mono/three-phase, limits and format compatibility");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{Directory.Delete(dir,true);}}
}
